org_id = #{orgId}, volunteer_id = #{volunteerId}, quantity = #{quantity}, amount = #{amount}, status = #{status}, address = #{address}, execute_images = #{executeImages}, pay_time = #{payTime}, complete_time = #{completeTime}, update_time = sysdate(),
where order_no = #{orderNo}

