    and status = #{status}

select count(1) from order_protect
where org_id = #{orgId}

    and DATE(create_time) >= #{startDate}


    and DATE(create_time) <= #{endDate}

select IFNULL(SUM(amount), 0) from order_protect
where org_id = #{orgId}

    and DATE(create_time) >= #{startDate}


    and DATE(create_time) <= #{endDate}

select op.order_no, op.create_time, s.name as species_name, op.quantity, op.amount, op.status as status_name from order_protect op left join species s on op.species_id = s.id where 1=1
and op.org_id = #{orgId}
and DATE(op.create_time) >= #{startDate}
and DATE(op.create_time) <= #{endDate}
order by op.create_time desc

